     ('REQ-25', 'IF digitale_methoden_bim_angewendet == true THEN (bim_project_definition_complete == true AND aia_available == true AND bap_defined == true AND cde_platform_defined == true)'),
     ('REQ-26', 'IF digitale_methoden_bim_angewendet == true THEN (digital_twin_after_project == true)'),
     ('REQ-27', 'bestandsdaten_complete_digital == true AND akz_in_place == true AND critical_infra_assessed == true'),
     ('REQ-29', 'IF digitale_methoden_bim_angewendet == true THEN (cde_used_for_communication == true AND bim_communication_interfaces == true)'),
     ('REQ-30', 'public_info_via_digital_media == true AND communication_concept_adaptive == true'),
     ('REQ-02', 'anw_hinweis_1_confirmed == true AND anw_hinweis_2_confirmed == true AND anw_hinweis_3_confirmed == true AND anw_hinweis_4_confirmed == true'),
     ('REQ-03', 'phase_definition_acknowledged == true AND phasenziele_definition_acknowledged == true AND projektziele_definition_acknowledged == true AND qe_definition_acknowledged == true'),
     ('REQ-05', 'IF kleiner_kommunaler_betrieb == true THEN (grundsatz_two_step_followed == true)'),
     ('REQ-31', 'IF projektstopp_code == 1 THEN (projektstopp_review_triggered == true)'));
DELETE FROM compliance_requirements_archive_m820_3_structure a USING compliance_requirements cr
 WHERE cr.id = a.id AND cr.condition = a.condition AND cr.worksheet_template_id = a.worksheet_template_id
   AND cr.clause_reference IS NOT DISTINCT FROM a.clause_reference AND cr.description IS NOT DISTINCT FROM a.description
   AND cr.title_de = a.title_de AND cr.title_en IS NOT DISTINCT FROM a.title_en;

-- 7⁻¹. visible_when back to the archived (NULL) value where the block's rule is still live
UPDATE fields f
   SET visible_when = a.visible_when
  FROM fields_archive_m820_3_structure a, worksheet_templates w,
       (VALUES ('M8203-02', 'grundsatz_two_step_followed', 'kleiner_kommunaler_betrieb == true'),
               ('M8203-19', 'aia_available', 'digitale_methoden_bim_angewendet == true'),
               ('M8203-19', 'bap_defined', 'digitale_methoden_bim_angewendet == true'),
               ('M8203-19', 'bim_project_definition_complete', 'digitale_methoden_bim_angewendet == true'),
               ('M8203-19', 'cde_platform_defined', 'digitale_methoden_bim_angewendet == true'),
               ('M8203-19', 'digital_twin_after_project', 'digitale_methoden_bim_angewendet == true'),
               ('M8203-21', 'bim_communication_interfaces', 'digitale_methoden_bim_angewendet == true'),
               ('M8203-21', 'cde_used_for_communication', 'digitale_methoden_bim_angewendet == true')) AS h(ws, sym, rule)
 WHERE a.id = f.id AND w.id = f.worksheet_template_id AND w.code = h.ws AND f.symbol = h.sym AND a.visible_when IS NULL AND f.visible_when = h.rule;

-- 6⁻¹. project_type reach back to '{ALL}' where it still carries exactly the block's list
UPDATE fields f
   SET consumer_worksheets = a.consumer_worksheets
  FROM fields_archive_m820_3_structure a
 WHERE a.id = f.id AND f.symbol = 'project_type'
   AND f.consumer_worksheets = ARRAY['M8203-04', 'M8203-05', 'M8203-06', 'M8203-07', 'M8203-08', 'M8203-09', 'M8203-10', 'M8203-11', 'M8203-12', 'M8203-13', 'M8203-14', 'M8203-15', 'M8203-16', 'M8203-17', 'M8203-18', 'M8203-22', 'M8203-23']::text[];

-- 1⁻¹. Phasenziel enums back to the archived four tokens where the list is still archive || the token
UPDATE fields f
   SET enum_values = a.enum_values
  FROM fields_archive_m820_3_structure a
 WHERE a.id = f.id AND f.symbol LIKE 'pz\_%\_status'
   AND f.enum_values = a.enum_values || '[{"value":"noch_nicht_erreicht","label_de":"Phase noch nicht erreicht (Bewertung erst nach Abschluss der Phase)","label_en":"Phase not reached yet (assessed once the phase is completed)","order_index":5,"regulation_reference":"§2.1 Phasenziele"}]'::jsonb;

DELETE FROM fields_archive_m820_3_structure a USING fields f
 WHERE f.id = a.id
   AND f.enum_values IS NOT DISTINCT FROM a.enum_values
   AND f.visible_when IS NOT DISTINCT FROM a.visible_when
   AND f.consumer_worksheets IS NOT DISTINCT FROM a.consumer_worksheets;

-- 5⁻¹. section rules back to the archived (NULL) value where the block's rule is still live
UPDATE worksheet_sections ws
   SET visible_when = a.visible_when
  FROM worksheet_sections_archive_m820_3_structure a
 WHERE a.id = ws.id AND a.visible_when IS NULL AND ws.visible_when IN ('project_type IN {''gesamtsystem'', ''both''}', 'project_type IN {''einzelprojekt'', ''both''}');
DELETE FROM worksheet_sections_archive_m820_3_structure a USING worksheet_sections ws
 WHERE ws.id = a.id AND ws.visible_when IS NOT DISTINCT FROM a.visible_when;

-- 2⁻¹. the eleven new fields and their saved values
DELETE FROM project_parameters p USING fields f, worksheet_templates w, standards s
 WHERE p.field_id = f.id AND f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-3'
   AND (w.code, f.symbol) IN (('M8203-04','pz_52_projektstopp_risikoanalyse'),('M8203-05','pz_53_projektstopp_risikoanalyse'),('M8203-06','pz_54_projektstopp_risikoanalyse'),('M8203-11','pz_62_projektstopp_risikoanalyse'),('M8203-12','pz_63_projektstopp_risikoanalyse'),('M8203-14','pz_64_projektstopp_risikoanalyse'),('M8203-16','pz_65_projektstopp_risikoanalyse'),('M8203-17','pz_66_projektstopp_risikoanalyse'),('M8203-18','pz_67_projektstopp_risikoanalyse'),('M8203-02','kleiner_kommunaler_betrieb'),('M8203-19','digitale_methoden_bim_angewendet'));
DELETE FROM fields f USING worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-3'
   AND (w.code, f.symbol) IN (('M8203-04','pz_52_projektstopp_risikoanalyse'),('M8203-05','pz_53_projektstopp_risikoanalyse'),('M8203-06','pz_54_projektstopp_risikoanalyse'),('M8203-11','pz_62_projektstopp_risikoanalyse'),('M8203-12','pz_63_projektstopp_risikoanalyse'),('M8203-14','pz_64_projektstopp_risikoanalyse'),('M8203-16','pz_65_projektstopp_risikoanalyse'),('M8203-17','pz_66_projektstopp_risikoanalyse'),('M8203-18','pz_67_projektstopp_risikoanalyse'),('M8203-02','kleiner_kommunaler_betrieb'),('M8203-19','digitale_methoden_bim_angewendet'));

COMMIT;
